<?php
session_start();require_once "config.php";if(!isset($_SESSION['user_id'])){header("Location:login.php");exit;}
$msg="";
if(isset($_POST['action'],$_POST['request_id'])){
 $rid=(int)$_POST['request_id'];$action=$_POST['action'];
 if($action==='approve'){$s=$conn->prepare("SELECT br.book_id,b.owner_id FROM borrow_requests br JOIN books b ON br.book_id=b.id WHERE br.id=? AND b.owner_id=?");$s->bind_param("ii",$rid,$_SESSION['user_id']);$s->execute();$r=$s->get_result()->fetch_assoc();if($r){$s=$conn->prepare("UPDATE borrow_requests SET status='Approved' WHERE id=?");$s->bind_param("i",$rid);$s->execute();$s=$conn->prepare("UPDATE books SET status='Borrowed' WHERE id=?");$s->bind_param("i",$r['book_id']);$s->execute();$msg="Request approved.";} }
 elseif($action==='reject'){$s=$conn->prepare("UPDATE borrow_requests br JOIN books b ON br.book_id=b.id SET br.status='Rejected' WHERE br.id=? AND b.owner_id=?");$s->bind_param("ii",$rid,$_SESSION['user_id']);$s->execute();$msg="Request rejected.";}
}
$incoming=$conn->prepare("SELECT br.*,b.title,u.name requester FROM borrow_requests br JOIN books b ON br.book_id=b.id JOIN users u ON br.requester_id=u.id WHERE b.owner_id=? ORDER BY br.created_at DESC");$incoming->bind_param("i",$_SESSION['user_id']);$incoming->execute();$incoming=$incoming->get_result();
$outgoing=$conn->prepare("SELECT br.*,b.title,u.name owner FROM borrow_requests br JOIN books b ON br.book_id=b.id JOIN users u ON b.owner_id=u.id WHERE br.requester_id=? ORDER BY br.created_at DESC");$outgoing->bind_param("i",$_SESSION['user_id']);$outgoing->execute();$outgoing=$outgoing->get_result();
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Requests</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><a class="brand" href="index.php">📚 BookBridge</a><nav><a href="books.php">Browse Books</a><a href="post-book.php">Post a Book</a><a href="profile.php">Profile</a><a class="btn small" href="logout.php">Logout</a></nav></header><main class="container page"><span class="eyebrow">BORROWING MANAGEMENT</span><h1>Requests</h1><?php if($msg):?><div class="success"><?=htmlspecialchars($msg)?></div><?php endif;?><h2>Requests for My Books</h2><div class="request-list"><?php while($r=$incoming->fetch_assoc()):?><div class="request"><div><strong><?=htmlspecialchars($r['title'])?></strong><p>Requested by <?=htmlspecialchars($r['requester'])?></p><small><?=htmlspecialchars($r['message'])?></small></div><div><span class="badge"><?=htmlspecialchars($r['status'])?></span><?php if($r['status']==='Pending'):?><form method="post" class="inline"><input type="hidden" name="request_id" value="<?=$r['id']?>"><button name="action" value="approve" class="btn small">Approve</button><button name="action" value="reject" class="btn small outline">Reject</button></form><?php endif;?></div></div><?php endwhile;?></div><h2>My Borrow Requests</h2><div class="request-list"><?php while($r=$outgoing->fetch_assoc()):?><div class="request"><div><strong><?=htmlspecialchars($r['title'])?></strong><p>Owner: <?=htmlspecialchars($r['owner'])?></p></div><span class="badge"><?=htmlspecialchars($r['status'])?></span></div><?php endwhile;?></div></main></body></html>
